#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <set>
#include <utility>
using namespace std;

int main(){
set<pair<int,int>>rationals;
for(int denominator=1;denominator<=8;denominator++)
    for(int numerator=0;numerator<=denominator;numerator++){
        int a=numerator,b=denominator;
        while(b){int remainder=a%b;a=b;b=remainder;}
        rationals.insert({numerator/a,denominator/a});
    }
cout<<"distinct rationals with denominator <= 8 "<<rationals.size()<<"
";
return 0;
}

